"""QA edge cases generated from the API contract. Do not edit; fix the code instead."""
import pytest
from fastapi.testclient import TestClient

from backend.main import app

client = TestClient(app)


def test_post_api_calculations_rejects_empty_body():
    assert client.post('/api/calculations', json={}).status_code == 422


def test_post_api_calculations_rejects_missing_a():
    assert client.post('/api/calculations', json={'b': 3, 'operation': 'add'}).status_code == 422


def test_post_api_calculations_rejects_non_numeric_a():
    assert client.post('/api/calculations', json={'a': 'not a number', 'b': 3, 'operation': 'add'}).status_code == 422


def test_post_api_calculations_rejects_missing_b():
    assert client.post('/api/calculations', json={'a': 5, 'operation': 'add'}).status_code == 422


def test_post_api_calculations_rejects_non_numeric_b():
    assert client.post('/api/calculations', json={'a': 5, 'b': 'not a number', 'operation': 'add'}).status_code == 422


def test_post_api_calculations_rejects_missing_operation():
    assert client.post('/api/calculations', json={'a': 5, 'b': 3}).status_code == 422


def test_posted_item_shows_up_in_the_list():
    r = client.post('/api/calculations', json={'a': 5, 'b': 3, 'operation': 'add'})
    assert r.status_code < 300, r.text
    items = client.get('/api/calculations').json()['items']
    assert len(items) == 1
    for k, v in {'a': 5, 'b': 3, 'operation': 'add'}.items():
        if k in items[0]:
            assert items[0][k] == (pytest.approx(v) if isinstance(v, (int, float)) and not isinstance(v, bool) else v)


def test_clearing_empties_the_list():
    client.post('/api/calculations', json={'a': 5, 'b': 3, 'operation': 'add'})
    r = client.delete('/api/calculations')
    assert r.status_code < 300, r.text
    assert client.get('/api/calculations').json()['items'] == []

